//
// FASTQ_CONTAM_SEQTK_KRAKEN: Subsample FASTQs and perform contamination screening
//
include { KRAKEN2_KRAKEN2 as KRAKEN2 } from 'nf-core/kraken2/kraken2'
include { SEQTK_SAMPLE               } from 'nf-core/seqtk/sample'

workflow FASTQ_CONTAM_SEQTK_KRAKEN {

    take:
        ch_reads    //channel: [mandatory] meta,reads
        sample_size //string:  [mandatory] number of reads to subsample
        kraken2_db  //string:  [mandatory] path to Kraken2 DB to use for screening

    main:
        ch_reports  = channel.empty()

        // Combine all combinations of reads with sample_size(s).
        // Note using more than 1 sample_size can cause file collisions
        // We add n_reads to meta to avoid collisions
        ch_reads
            .combine(sample_size)
            .map{ it ->
                def meta2 = it[0] + [n_reads: it[2]]
                [ meta2, it[1], it[2] ]
            }
            .set { ch_reads_with_n }

        SEQTK_SAMPLE(ch_reads_with_n)

        // SEQTK_SAMPLE emits version as a topic channel

        KRAKEN2(SEQTK_SAMPLE.out.reads,
                kraken2_db,
                false,
                false
        )
        ch_reports  = ch_reports.mix(KRAKEN2.out.report)

    emit:
        reports  = ch_reports              // channel: [ [meta], log  ]
        reads    = SEQTK_SAMPLE.out.reads // channel: [ [meta], reads  ]
}

nextflow_workflow {

    name "Test Workflow FASTQ_CONTAM_SEQTK_KRAKEN"
    config "./nextflow.config"
    script "../main.nf"
    workflow "FASTQ_CONTAM_SEQTK_KRAKEN"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/fastq_contam_seqtk_kraken"
    tag "fastq_contam_seqtk_kraken"

    tag "kraken2/kraken2"
    tag "seqtk/sample"
    tag "kraken2"
    tag "seqtk"

    test("sarscov2 - fastq - 25000 - krakendb") {
        def db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
        }

        when {
            workflow {
                """
                input[0] = channel.of([
                    [id:'test', single_end:true],
                    [file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true)],
                ])
                input[1] = channel.of(25000)
                input[2] = file('${db}')
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }
    test("sarscov2 - fastq - [12500, 25000] - krakendb") {
        def db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
        }

        when {
            workflow {
                """
                input[0] = channel.of([
                    [id:'test', single_end:true],
                    [file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true)],
                ])
                input[1] = channel.of(12500,25000)
                input[2] = file('${db}')
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }
    test("sarscov2 - fastq - [12500, 25000] - krakendb -- stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id:'test', single_end:true],
                    [file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true)],
                ])
                input[1] = channel.of(12500,25000)
                input[2] = []
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    workflow.out,
                    workflow.out.versions.collect{ path(it).yaml }
                ).match() }
            )
        }
    }
}

